package com.iamguru.AI.testdata;

public class User {

    private String firstName;
    private String lastName;
    private String email;
    private String phone;
    private String password;
    private String confirmPassword;
    private String address;
    private String zipCode;

    private String url;
    private String agentName;
    private String domain;
	private String domainUrl;

    public String getFirstName() { return firstName; }
    public void setFirstName(String firstName) { this.firstName = firstName; }

    public String getLastName() { return lastName; }
    public void setLastName(String lastName) { this.lastName = lastName; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }
    
    public String getDomainUrl() { return domainUrl; }
    public void setDomainUrl(String domainUrl) { this.domainUrl = domainUrl; }

    public String getPhone() { return phone; }
    public void setPhone(String phone) { this.phone = phone; }

    public String getPassword() { return password; }
    public void setPassword(String password) { this.password = password; }
    
    public String getconfirmPassword() { return confirmPassword; }
    public void setconfirmPassword(String confirmPassword) { this.confirmPassword = confirmPassword; }

    public String getAddress() { return address; }
    public void setAddress(String address) { this.address = address; }
    
    
    public String getZipCode() { return zipCode; }
    public void setZipCode(String zipCode) { this.zipCode = zipCode; }

    public String getUrl() { return url; }
    public void setUrl(String url) { this.url = url; }
    
    public String getknowledgebaseurl() { return domainUrl; }
    public void setknowledgebaseurl(String domainUrl) { this.domainUrl = domainUrl; }

    public String getAgentName() { return agentName; }
    public void setAgentName(String agentName) { this.agentName = agentName; }

    public String getDomain() { return domain; }
    public void setDomain(String domain) { this.domain = domain; }
	
}